const runId = `${$now.toMillis()}-${Math.floor(Math.random() * 1e6)}`;
const COUNT = 5;

// A small batch, not the full MAX_BULK_ENTITIES cap (nodes/Enterspeed/actions/entity/shared.ts)
// — keeps this CI step fast while still exercising the real saveBulk/deleteBulk code path.
// Shaped like a real `product` entity (see docs.enterspeed.com/api-reference/ingest/save-entities)
// rather than a minimal test payload, since that's what this bulk path actually ingests in production.
const entities = [];
for (let i = 1; i <= COUNT; i++) {
  const originId = `e2e-bulk-${runId}-${i}`;
  const sku = `ENT-E2E-${runId}-${i}`;
  entities.push({
    type: 'product',
    originId,
    originParentId: null,
    url: `/products/e2e-bulk-test-${runId}-${i}`,
    redirects: [],
    properties: {
      sku,
      productName: `E2E Bulk Test Product ${i}`,
      category: 'Footwear > Outdoor > Hiking',
      brand: 'TrailForm',
      priceExclVat: 899,
      currency: 'DKK',
      stockStatus: 'In Stock',
      stockQuantity: 142,
      colour: 'Slate Grey / Burnt Orange',
      sizeRange: 'EU 38-46',
      material: 'Recycled mesh upper, rubber outsole',
      weightGrams: 340,
    },
  });
}

return [{
  json: {
    entities,
    originIds: entities.map((e) => e.originId),
  },
}];

const { entities } = $('Build Test Entities').first().json;
return entities.map((e) => ({
  json: { originId: e.originId, url: e.url, sku: e.properties.sku },
}));

// Delivery is eventually consistent: ingest and processing are asynchronous, so poll
// every 5 s (the Wait node on the loop) instead of guessing a fixed delay, up to a ceiling.
const MAX_ATTEMPTS = 18; // 18 × 5 s = 90 s
const attempt = $runIndex + 1;
const expected = $('Prepare Exists Check').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

// Get Content answers one item per input item, in order.
const results = expected.map((e, idx) => ({ originId: e.originId, url: e.url, sku: e.sku, response: responses[idx] }));
const allPresent = results.every((r) => r.response?.route?.sku === r.sku);
const settled = allPresent || attempt >= MAX_ATTEMPTS;

return results.map((r) => ({ json: { ...r, attempt, settled } }));

// Records a failure instead of throwing, so Delete Bulk still runs and removes the
// test products on a red run. Assert All Checks Passed fails the workflow at the end.
const { originId, url, sku, response, attempt } = $json;
const route = response?.route;

let failure = null;
if (!route) {
  failure = `Entity ${originId} has no route ${attempt} polls after Save Bulk, so it was not created. Delivery answered ${JSON.stringify(response)}`;
} else if (route.sku !== sku) {
  failure = `Entity ${originId} route.sku is ${JSON.stringify(route.sku)}, expected "${sku}"`;
}

return { json: { originId, url, sku, exists: failure === null, attempts: attempt, failure } };

// Delete Bulk runs on the same origin ids whatever the checks above found: it is
// both the operation under test and the clean-up of this run's test products.
return [{ json: { originIds: $('Build Test Entities').first().json.originIds } }];

const { entities } = $('Build Test Entities').first().json;
return entities.map((e) => ({
  json: { originId: e.originId, url: e.url, sku: e.properties.sku },
}));

// Delivery is eventually consistent: ingest and processing are asynchronous, so poll
// every 5 s (the Wait node on the loop) instead of guessing a fixed delay, up to a ceiling.
const MAX_ATTEMPTS = 18; // 18 × 5 s = 90 s
const attempt = $runIndex + 1;
const expected = $('Prepare Deleted Check').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

// nodes/Enterspeed/actions/router.ts reports a continueOnFail'd request as
// { error, description } instead of throwing; Delivery itself answers an unknown
// URL with route: null and meta.status 404. Either one means the entity is gone.
const isGone = (response, sku) => {
  const hasLiveRoute = response?.route && response.route.sku === sku;
  const reportedMissing = typeof response?.error === 'string' || response?.route === null;
  return !hasLiveRoute && reportedMissing;
};

const results = expected.map((e, idx) => ({ originId: e.originId, url: e.url, sku: e.sku, response: responses[idx] }));
const allGone = results.every((r) => isGone(r.response, r.sku));
const settled = allGone || attempt >= MAX_ATTEMPTS;

return results.map((r) => ({ json: { ...r, attempt, settled } }));

// Records a failure instead of throwing; Assert All Checks Passed fails the workflow.
const { originId, url, sku, response, attempt } = $json;

let failure = null;
if (response?.route && response.route.sku === sku) {
  failure = `Entity ${originId} is still served ${attempt} polls after Delete Bulk (route.sku ${response.route.sku})`;
} else if (typeof response?.error !== 'string' && response?.route !== null) {
  failure = `Entity ${originId} got neither a clear not-found nor a live route after Delete Bulk. Delivery answered ${JSON.stringify(response)}`;
}

return { json: { originId, url, sku, deleted: failure === null, attempts: attempt, failure } };

// MAX_BULK_ENTITIES + 1 made-up origin ids (MAX_BULK_ENTITIES is 50 in
// nodes/Enterspeed/actions/entity/shared.ts; tests/workflow-templates.test.ts keeps
// OVER_LIMIT in step with it). The node leaves the limit to the Ingest API, which
// refuses the whole request with 422 before deleting anything.
const OVER_LIMIT = 51;
const { originIds } = $('Build Test Entities').first().json;
const prefix = originIds[0].replace(/-1$/, '');
return [{ json: { originIds: Array.from({ length: OVER_LIMIT }, (_, i) => `${prefix}-over-limit-${i + 1}`) } }];

// Fails the workflow, and so CI, if any check above failed. It runs after Delete Bulk,
// so a red run has already removed its test products.
const failures = [];

const saved = $('Save Entities (Bulk)').first().json;
if (typeof saved.error === 'string') {
  failures.push(`Save Bulk failed: ${saved.error}${saved.description ? ` (${saved.description})` : ''}`);
}

for (const { json } of $('Verify Entities Exist').all()) {
  if (json.failure) failures.push(json.failure);
}

const deleted = $('Delete Entities (Bulk)').first().json;
if (typeof deleted.error === 'string') {
  failures.push(`Delete Bulk failed, so this run's test products may be left behind: ${deleted.error}${deleted.description ? ` (${deleted.description})` : ''}`);
}

for (const { json } of $('Verify Entities Deleted').all()) {
  if (json.failure) failures.push(json.failure);
}

// The Ingest API refuses an over-limit bulk delete with 422 before deleting anything
// (its body says "Request contains 51 originIds but maximum allowed is 50"). With
// continue-on-fail the node reports n8n's message for a 422, and its description
// carries the status (or the API's message, if n8n parses the body).
const OVER_LIMIT_422 = 'Your request is invalid or could not be processed by the service';
const overLimit = $('Delete Entities (Bulk, Over Limit)').first().json;
const count = $('Build Over-Limit Origin IDs').first().json.originIds.length;
if (overLimit.error !== OVER_LIMIT_422 || !/\b422\b|maximum allowed is 50/.test(String(overLimit.description))) {
  failures.push(`Delete Bulk with ${count} origin ids should be refused with 422, but the node answered ${JSON.stringify(overLimit)}`);
}

if (failures.length > 0) {
  throw new Error(`${failures.length} check(s) failed:\n${failures.join('\n')}`);
}

return [{ json: { saved: $('Build Test Entities').first().json.originIds.length, exists: true, deleted: true, overLimitRefused: overLimit.error, overLimitDetail: overLimit.description } }];
